import {icon,escapeHtml as esc} from './components.js';
import {percentage,price} from './data.js';
import {sectorMark,sectorSymbol} from './sector-symbols.js';
const direction=value=>value>0?'up':value<0?'negative':'neutral-text';
export function historyDetailMarkup(record,day,sectorId,basis){
 const reconstructed=basis==='reconstructed',sector=record?.sectors.find(s=>s.id===sectorId),label=sector?sectorSymbol(sector).label:null;
 const header='<div class="dialog-heading"><div><div class="eyebrow">SECTOR JOURNAL</div><h2 id="history-detail-title">'+esc(sector?day+' · '+label+' 종목':day+' 섹터 기록')+'</h2></div><button class="icon-button" data-history-action="close" aria-label="섹터 기록 닫기">'+icon('close')+'</button></div>';
 if(!record)return header+'<div class="history-detail-body"><div class="data-state empty">'+icon('calendar')+'<strong>이 날짜의 기록이 없습니다</strong><p>'+(reconstructed?'휴장일이거나 계산할 일봉이 부족한 날짜입니다.':'실제로 관측한 날짜부터 차곡차곡 저장합니다.')+'</p></div></div>';
 const note='<p class="history-detail-note">'+esc(record.calculation)+'</p>'+(reconstructed?'<p class="history-detail-note history-reconstructed-note">현재 구성종목 '+record.totalStockCount+'개 중 '+record.stockCount+'개 사용 · '+record.missingCount+'개 일봉 누락 또는 상장 전<br>'+esc(record.coverageNote)+'</p><p class="history-detail-note">'+esc(record.adjustmentNote)+'<br>구성종목 확인일 '+esc(record.membershipObservedAt?.slice(0,10)||'미제공')+' · '+esc(record.source)+'</p>':'<p class="history-detail-note">'+esc(record.source||'연결된 공급처')+' · 당일 마지막 관측분 · 시세 기준시각 '+(record.sourceAsOf?'제공':'미제공')+'</p>');
 const intro='<p class="history-detail-intro">'+esc(record.universe)+' · '+record.stockCount+'개 종목 · '+esc(record.recordBasis||(reconstructed?(record.market==='KR'?'한국':'미국')+' 거래일 · 과거 재계산':'한국시간 관측일'))+'</p>';
 if(sector){
  const stocks=[...(sector.stocks||[])].sort((a,b)=>b.changePct-a.changePct||a.ticker.localeCompare(b.ticker));
  return header+'<div class="history-detail-body"><button class="history-detail-back" data-history-action="sectors">'+icon('chevron')+' 전체 섹터 순위</button>'+intro+'<div class="history-sector-summary">'+sectorMark(sector)+'<span><strong>'+esc(label)+'</strong><small>'+esc(sector.name)+' · '+sector.stockCount+'개 종목</small></span><b class="'+direction(sector.changePct)+'">'+percentage(sector.changePct)+'</b></div><p class="history-stock-context">'+(reconstructed?esc(day)+' 종가·등락률 · 계산에 포함한 종목 · 동일 비중':'이 날짜에 저장한 종목별 시세 · 관측 시가총액 비중')+'</p>'+(stocks.length?'<div class="history-stock-columns" aria-hidden="true"><span>종목 · 계산 비중</span><span>'+(reconstructed?'당일 종가':'관측 현재가')+'</span><span>전일 대비</span></div><div class="history-stock-list">'+stocks.map(stock=>'<button class="history-stock-row" data-history-action="stock" data-stock="'+esc(stock.id)+'" aria-label="'+esc(stock.name+' '+stock.ticker)+' 종목 상세 보기"><span class="history-stock-name"><strong>'+esc(stock.ticker)+'</strong><span>'+esc(stock.name)+'</span><small>'+(Number.isFinite(stock.weight)?(stock.weight*100).toFixed(2)+'% 비중':'비중 미제공')+(stock.industryName?' · '+esc(stock.industryName):'')+'</small></span><span class="history-stock-price">'+price(stock)+'</span><b class="'+direction(stock.changePct)+'">'+percentage(stock.changePct)+'</b></button>').join('')+'</div><p class="history-detail-note">종목을 누르면 현재 종목 상세 페이지로 이동합니다.</p>':'<div class="data-state empty"><strong>이 기록에는 종목별 내역이 없습니다</strong><p>이전에 저장된 섹터 요약 기록입니다. 당시 종목별 수치를 임의로 채우지 않습니다.</p></div>')+note+'</div>';
 }
 return header+'<div class="history-detail-body">'+intro+'<p class="history-stock-context">섹터를 누르면 해당 날짜의 종목별 내역을 볼 수 있어요.</p><ol class="history-rank-list">'+record.sectors.map((s,i)=>'<li><button class="history-sector-link" data-history-action="sector" data-sector="'+esc(s.id)+'" aria-label="'+esc(sectorSymbol(s).label)+' 종목별 내역 보기"><span class="history-rank-number">'+(i+1)+'</span>'+sectorMark(s)+'<span class="history-sector-name"><strong>'+esc(sectorSymbol(s).label)+'</strong><small>'+esc(s.name)+' · '+s.stockCount+(reconstructed?' / '+s.totalStockCount:'')+'개 종목</small></span>'+(record.strong.includes(s.id)?'<span class="history-rank-tag">강세</span>':record.weak.includes(s.id)?'<span class="history-rank-tag weak">약세</span>':'')+'<b class="'+direction(s.changePct)+'">'+percentage(s.changePct)+'</b>'+icon('chevron')+'</button></li>').join('')+'</ol>'+note+'</div>';
}
